#!/usr/bin/env node
/**
 * Build `lib/index.js` — the plugin's node half — without a dsh source checkout.
 *
 * The official path is `scripts/build-client.mjs`, which runs the dsh client-bundle
 * preset (tsdown) and needs `packages/client/tsdown.client.ts` from a harness
 * checkout. This repo has none, and the node half is two small ES modules, so this
 * script performs the one transformation the preset's Node build face performs
 * here: concatenate the tsc output under `lib/types` into one flat ESM file,
 * dropping the intra-package imports and re-exporting the entry module's exports.
 *
 * Run `npm run build` (tsc) first. Usage: node scripts/bundle-node.mjs
 */
import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const repo = resolve(dirname(fileURLToPath(import.meta.url)), '..')
/** Node-half modules in dependency order; the last one is the package entry. */
const modules = ['folder-layer', 'session-folders', 'index']

/** Tabs, the way the preset's output is formatted. */
const toTabs = (line) => line.replace(/^ +/, spaces => '\t'.repeat(Math.floor(spaces.length / 4)) + ' '.repeat(spaces.length % 4))

const externalImports = new Set()
const exportedNames = []
const regions = []

for (const name of modules) {
  const source = join(repo, 'lib', 'types', `${name}.js`)
  const lines = readFileSync(source, 'utf8').split('\n')
  const body = []
  for (const line of lines) {
    if (line.startsWith('//# sourceMappingURL=')) continue
    if (/^import .* from ['"]\.\/[^'"]+['"];?$/.test(line)) continue
    if (/^import .* from ['"]node:/.test(line)) {
      externalImports.add(line)
      continue
    }
    const exported = /^export (?:async )?(const|function|class|let|var) (\w+)/.exec(line)
    if (exported !== null) {
      if (name === modules.at(-1)) exportedNames.push(exported[2])
      body.push(toTabs(line.replace(/^export /, '')))
      continue
    }
    body.push(toTabs(line))
  }
  regions.push({ name, body: body.join('\n').replace(/\n+$/, '') })
}

if (exportedNames.length === 0) throw new Error('bundle-node: entry module exports nothing')

const out = [
  '// Generated by scripts/bundle-node.mjs from lib/types — do not edit.',
  ...[...externalImports],
  ...regions.flatMap(({ name, body }) => [`//#region lib/types/${name}.js`, body, '//#endregion']),
  `export { ${exportedNames.join(', ')} };`,
  '',
].join('\n')

writeFileSync(join(repo, 'lib', 'index.js'), out, 'utf8')
console.log(`bundle-node: lib/index.js (${regions.length} modules, exports ${exportedNames.join(', ')})`)
